function solve(input) {
  const seen = new Set();
  const sums = {};
  for (const { eventId, account, delta } of input) {
    if (!seen.has(eventId)) {
      seen.add(eventId);
      sums[account] = (sums[account] ?? 0) + delta;
    }
  }
  const result = Object.keys(sums).map(account => [account, sums[account]]);
  result.sort((a, b) => a[0].localeCompare(b[0]));
  return result;
}

