function solve(input) {
  const result = {};
  for (const { key, version, op, value } of input) {
    if (op === "delete") {
      if (key in result) {
        delete result[key];
      }
    } else {
      if (!(key in result) || version > result[key].version) {
        result[key] = { value, version };
      }
    }
  }
  const final = {};
  for (const [k, v] of Object.entries(result)) {
    final[k] = v.value;
  }
  return final;
}

