function solve(input) {
  const cache = new Map();
  const results = [];
  for (const op of input) {
    if (op.op === 'put') {
      const { t, key, value, ttl } = op;
      const expiry = t + ttl;
      cache.set(key, { value, expiry });
    } else if (op.op === 'get') {
      const { t, key } = op;
      const entry = cache.get(key);
      if (entry && entry.expiry > t) {
        results.push(entry.value);
      } else {
        results.push(null);
      }
    } else if (op.op === 'delete') {
      const { t, key } = op;
      cache.delete(key);
    }
  }
  return results;
}

