function solve(input) {
  const doc = input.document;
  const ptr = input.pointer;

  if (ptr === '') {
    return { found: true, value: doc };
  }

  if (typeof ptr !== 'string' || !ptr.startsWith('/')) {
    return { found: false };
  }

  const parts = ptr.slice(1).split(/~0|~1/);
  const decoded = [];
  for (let i = 0; i < parts.length; i += 2) {
    decoded.push(parts[i].replace(/~1/g, '/'));
    if (i + 1 < parts.length) {
      decoded.push(parts[i + 1]);
    }
  }
  if (parts.length % 2 === 1) {
    decoded.push('');
  }

  let current = doc;
  for (const key of decoded) {
    if (current === null || typeof current !== 'object') {
      return { found: false };
    }
    if (key === '') {
      return { found: true, value: current };
    }
    if (Array.isArray(current) && /^\d+$/.test(key) && !key.startsWith('0') && key !== '0') {
      return { found: false };
    }
    if (Array.isArray(current) && /^\d+$/.test(key)) {
      const idx = Number(key);
      if (idx < 0 || idx >= current.length) {
        return { found: false };
      }
      current = current[idx];
    } else {
      if (!(key in current)) {
        return { found: false };
      }
      current = current[key];
    }
  }
  return { found: true, value: current };
}

